type Part = { corr: string; seq: number; size: number; body: string };

async function* splitLines(src: AsyncIterable<string>, corr: string)
  : AsyncGenerator<Part> {
  let seq = 0;
  for await (const line of src)
    yield { corr, seq: seq++, size: 0, body: line };
}
